#ifndef CBLUEPRINT_REGISTRY_H
#define CBLUEPRINT_REGISTRY_H

#include "array_nodes.h"
#include "node.h"
#include "operator.h"
#include "reroute_nodes.h"
#include "service.h"
#include "set_map_nodes.h"
#include "state_nodes.h"
#include "struct_nodes.h"
#include "switch_nodes.h"

#include <string.h>

/* Fail fast at init: assert every registered descriptor satisfies its
 * pure_kind invariants (see core/validate.c). */
void registry_validate(void);

/* Generated by reflect (generated/registry.c), compiled into core. */
extern node_desc *const REGISTRY_NODES[];
extern const int REGISTRY_NODE_COUNT;
extern const type_desc *const REGISTRY_TYPES[];
extern const int REGISTRY_TYPE_COUNT;
extern const service_desc *const REGISTRY_SERVICES[];
extern const int REGISTRY_SERVICE_COUNT;
extern const operator_signature REGISTRY_OPERATORS[];
extern const int REGISTRY_OPERATOR_COUNT;

/* Hand-written nodes (core/const_nodes.c), compiled into core. */
extern node_desc *const EXTRA_NODES[];
extern const int EXTRA_NODE_COUNT;

extern node_desc *const FLOW_NODES[];
extern const int FLOW_NODE_COUNT;
extern node_desc NODE_Event, NODE_Branch, NODE_Sequence, NODE_ForLoop,
    NODE_ForLoopWithBreak, NODE_WhileLoop, NODE_ForEach, NODE_ForEachWithBreak,
    NODE_Break, NODE_Delay, NODE_PrintString, NODE_GetVariable,
    NODE_SetVariable, NODE_Self, NODE_CallEvent, NODE_FunctionEntry,
    NODE_Return, NODE_CallFunction, NODE_CallPureFunction, NODE_CallMacro,
    NODE_SwitchInt, NODE_SwitchString, NODE_SwitchName, NODE_SwitchEnum,
    NODE_Select, NODE_RerouteData, NODE_RerouteExec, NODE_SetMembers;

static inline int registry_node_count(void)
{
    return REGISTRY_NODE_COUNT + EXTRA_NODE_COUNT + FLOW_NODE_COUNT +
           ARRAY_NODE_COUNT + STATE_NODE_COUNT + SWITCH_NODE_COUNT +
           REROUTE_NODE_COUNT + SET_MAP_NODE_COUNT + STRUCT_NODE_COUNT;
}

/* NULL if i is out of range. */
static inline const node_desc *registry_node(int i)
{
    if (i < 0) {
        return NULL;
    }
    if (i < REGISTRY_NODE_COUNT) {
        return REGISTRY_NODES[i];
    }
    i -= REGISTRY_NODE_COUNT;
    if (i < EXTRA_NODE_COUNT) {
        return EXTRA_NODES[i];
    }
    i -= EXTRA_NODE_COUNT;
    if (i < FLOW_NODE_COUNT) {
        return FLOW_NODES[i];
    }
    i -= FLOW_NODE_COUNT;
    if (i < ARRAY_NODE_COUNT) {
        return ARRAY_NODES[i];
    }
    i -= ARRAY_NODE_COUNT;
    if (i < STATE_NODE_COUNT) {
        return STATE_NODES[i];
    }
    i -= STATE_NODE_COUNT;
    if (i < SWITCH_NODE_COUNT) {
        return SWITCH_NODES[i];
    }
    i -= SWITCH_NODE_COUNT;
    if (i < REROUTE_NODE_COUNT) {
        return REROUTE_NODES[i];
    }
    i -= REROUTE_NODE_COUNT;
    if (i < SET_MAP_NODE_COUNT) {
        return SET_MAP_NODES[i];
    }
    i -= SET_MAP_NODE_COUNT;
    if (i >= STRUCT_NODE_COUNT) {
        return NULL;
    }
    return STRUCT_NODES[i];
}

/* NULL if no node type is named `name`. */
static inline const node_desc *registry_node_by_name(const char *name)
{
    for (int i = 0; i < REGISTRY_NODE_COUNT; i++) {
        if (strcmp(REGISTRY_NODES[i]->name, name) == 0) {
            return REGISTRY_NODES[i];
        }
    }
    for (int i = 0; i < EXTRA_NODE_COUNT; i++) {
        if (strcmp(EXTRA_NODES[i]->name, name) == 0) {
            return EXTRA_NODES[i];
        }
    }
    for (int i = 0; i < FLOW_NODE_COUNT; i++) {
        if (strcmp(FLOW_NODES[i]->name, name) == 0) {
            return FLOW_NODES[i];
        }
    }
    for (int i = 0; i < ARRAY_NODE_COUNT; i++) {
        if (strcmp(ARRAY_NODES[i]->name, name) == 0) {
            return ARRAY_NODES[i];
        }
    }
    for (int i = 0; i < STATE_NODE_COUNT; i++) {
        if (strcmp(STATE_NODES[i]->name, name) == 0) {
            return STATE_NODES[i];
        }
    }
    for (int i = 0; i < SWITCH_NODE_COUNT; i++) {
        if (strcmp(SWITCH_NODES[i]->name, name) == 0) {
            return SWITCH_NODES[i];
        }
    }
    for (int i = 0; i < REROUTE_NODE_COUNT; i++) {
        if (strcmp(REROUTE_NODES[i]->name, name) == 0) {
            return REROUTE_NODES[i];
        }
    }
    for (int i = 0; i < SET_MAP_NODE_COUNT; i++) {
        if (strcmp(SET_MAP_NODES[i]->name, name) == 0) {
            return SET_MAP_NODES[i];
        }
    }
    for (int i = 0; i < STRUCT_NODE_COUNT; i++) {
        if (strcmp(STRUCT_NODES[i]->name, name) == 0) {
            return STRUCT_NODES[i];
        }
    }
    return NULL;
}

#endif
